parameters.jsCode:
// Cheap local pre-filter. The AI agent is expensive — roughly 12k tokens per
// announcement — so it must only ever see announcements that could plausibly matter.
// Exclusions win over keywords: a tender for "licences for a warehouse system"
// is a resale deal, not a build, no matter how many software words it contains.
const cfg = $('Set API and Keywords').first().json;
const store = $getWorkflowStaticData('global');
store.seen = store.seen || [];

let list = [];
for (const item of $input.all()) {
  const r = item.json;
  const d = r?.data || r;
  if (Array.isArray(d?.advertisements)) list.push(...d.advertisements);
}
if (!list.length) {
  throw new Error('No announcements in the response. Inspect the "Fetch announcements" node output.');
}

const strip = s => String(s ?? '').toLowerCase()
  .replace(/ł/g,'l').replace(/ą/g,'a').replace(/ę/g,'e').replace(/ś/g,'s')
  .replace(/ć/g,'c').replace(/ż/g,'z').replace(/ź/g,'z').replace(/ó/g,'o').replace(/ń/g,'n');

const KEEP = String(cfg.keywords || '').split(',').map(s => strip(s.trim())).filter(Boolean);
const DROP = String(cfg.excludeKeywords || '').split(',').map(s => strip(s.trim())).filter(Boolean);
const REGION = String(cfg.regions || '').split(',').map(s => strip(s.trim())).filter(Boolean);
const MIN_DAYS = Number(cfg.minDaysToDeadline || 5);
const MAX = Number(cfg.maxPerRun || 8);

const now = new Date();
const hits = [];

for (const a of list) {
  const id = String(a.id ?? '');
  if (!id || store.seen.includes(id)) continue;
  store.seen.push(id);
  if (a.is_mine === true) continue;

  const text = strip((a.title || '') + ' ' + (a.content || ''));
  const place = strip(a.fulfillment_place || '');

  if (DROP.some(w => text.includes(w))) continue;
  if (KEEP.length && !KEEP.some(w => text.includes(w))) continue;
  if (REGION.length && !REGION.some(w => place.includes(w))) continue;

  let days = null;
  if (a.submission_deadline) {
    const d = new Date(String(a.submission_deadline).replace(' ', 'T'));
    if (!isNaN(d)) days = Math.ceil((d - now) / 86400000);
  }
  if (days !== null && days < MIN_DAYS) continue;

  hits.push({ json: {
    id,
    days_to_deadline: days,
    title: a.title || '',
    summary: String(a.content || '').slice(0, 600),
    buyer: a.advertiser_name || '',
    place: a.fulfillment_place || '',
    deadline: a.submission_deadline || '',
    published: a.publication_date || '',
    url: (cfg.publicUrlBase || '') + id,
  }});
}

if (store.seen.length > 6000) store.seen = store.seen.slice(-4000);
hits.sort((a, b) => (a.json.days_to_deadline ?? 999) - (b.json.days_to_deadline ?? 999));
return hits.slice(0, MAX);

parameters.text:
=You are a bid qualification analyst. Decide whether the company you work for should spend time preparing an offer for this public tender.

=== ANNOUNCEMENT ===
ID: {{ $json.id }}
Title: {{ $json.title }}
Buyer: {{ $json.buyer }}
Place: {{ $json.place }}
Deadline: {{ $json.deadline }} ({{ $json.days_to_deadline }} days left)
Summary: {{ $json.summary }}

=== YOUR COMPANY PROFILE ===
{{ $('Set API and Keywords').first().json.companyProfile }}

=== HARD DISQUALIFIERS — any one of these means NO_GO ===
{{ $('Set API and Keywords').first().json.dealBreakers }}

=== INSTRUCTIONS ===
The summary above is truncated and never contains the award criteria, the estimated value or the contact person. Use the `tender_details` tool with the announcement ID to fetch the full record whenever the decision depends on information you do not have — especially the award criteria, because a tender where price carries most of the weight is a price auction, not a fit.

Do not invent facts. If something is genuinely unknown after using the tool, say so in `open_questions` rather than guessing.

Be decisive. A borderline GO that wastes two days of work is worse than an honest NO_GO.

parameters.jsCode:
// One message per qualified tender. NO_GO results are kept in the output but not sent —
// they are useful for tuning the profile, not for interrupting anyone.
const cfg = $('Set API and Keywords').first().json;
const rows = $input.all().map(i => i.json?.output ?? i.json);

const worth = rows.filter(r => r && r.verdict && r.verdict !== 'NO_GO');
if (!worth.length) return [];

const lines = [];
lines.push(`${worth.length} tender(s) worth a look`);
lines.push('');

for (const r of worth) {
  lines.push(`[${r.verdict}] ${r.one_line_reason}`);
  if (r.price_weight_percent != null) lines.push(`Price weight: ${r.price_weight_percent}%`);
  if (r.estimated_value) lines.push(`Estimated value: ${r.estimated_value}`);
  if (r.contact) lines.push(`Contact: ${r.contact}`);
  if (r.condition_to_verify) lines.push(`Verify first: ${r.condition_to_verify}`);
  if (r.scope_outside_our_wheelhouse) lines.push(`Outside our scope: ${r.scope_outside_our_wheelhouse}`);
  if (Array.isArray(r.open_questions) && r.open_questions.length) {
    lines.push('Ask the buyer:');
    r.open_questions.slice(0, 4).forEach(q => lines.push('  - ' + q));
  }
  lines.push('');
}

return [{ json: { text: lines.join('\n').slice(0, 3900), count: worth.length, results: rows } }];
